function Topbar({ onMobileMenu }: { onMobileMenu: () => void }) {
  const [location] = useLocation();
  const page = navItems.find(item => item.href === location)?.label ?? 'Overview';
  const [notice, setNotice] = useState('');
  const notify = (value: string) => { setNotice(value); window.setTimeout(() => setNotice(''), 2400); };
  return <header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-border bg-background/95 px-5 backdrop-blur md:px-8">
    <div className="flex items-center gap-3"><button onClick={onMobileMenu} data-testid="button-mobile-menu" className="rounded-md p-2 text-muted-foreground hover:bg-muted md:hidden"><Menu size={19} /></button><div><p className="text-[11px] font-semibold uppercase tracking-[.16em] text-muted-foreground">Workspace / <span className="text-foreground">{page}</span></p><p className="mt-1 hidden text-xs text-muted-foreground sm:block">Thursday, October 24, 2024 <span className="mx-1.5 text-border">•</span> Last sync 2m ago</p></div></div>
    <div className="relative flex items-center gap-2.5"><button onClick={() => notify('No new workspace notifications.')} data-testid="button-notifications" className="relative rounded-md p-2 text-muted-foreground hover:bg-muted hover:text-foreground"><Bell size={18} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-primary" /></button><div className="hidden h-6 w-px bg-border sm:block" /><button onClick={() => notify('Signed in as Avery Ross.')} data-testid="button-user-menu" className="flex items-center gap-2 rounded-md px-1.5 py-1 text-left hover:bg-muted"><span className="grid h-7 w-7 place-items-center rounded-full bg-secondary text-[10px] font-bold text-secondary-foreground">AR</span><span className="hidden text-xs font-semibold sm:block">Avery Ross</span><ChevronDown size={14} className="hidden text-muted-foreground sm:block" /></button>{notice && <div className="absolute right-0 top-12 whitespace-nowrap rounded-md border border-border bg-card px-3 py-2 text-[11px] font-semibold shadow-lg animate-rise-in" data-testid="status-topbar-notice">{notice}</div>}</div>
  </header>;
}

function Shell({ children }: { children: ReactNode }) {
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  return <div className="min-h-[100dvh] bg-background"><div className={cls('hidden md:block', collapsed ? 'md:w-[72px]' : 'md:w-[236px]')} /><div className={cls(mobileOpen ? 'block' : 'hidden', 'md:hidden')}><div onClick={() => setMobileOpen(false)} className="fixed inset-0 z-30 bg-foreground/30" /><div className="fixed inset-y-0 left-0 z-40 w-[236px]"><Sidebar collapsed={false} onCollapse={() => setMobileOpen(false)} /></div></div><div className="hidden md:block"><Sidebar collapsed={collapsed} onCollapse={() => setCollapsed(value => !value)} /></div><div className={cls('min-h-[100dvh] transition-[margin] duration-300', collapsed ? 'md:ml-[72px]' : 'md:ml-[236px]')}><Topbar onMobileMenu={() => setMobileOpen(true)} /><main className="mx-auto max-w-[1520px] px-5 py-7 md:px-8 md:py-9">{children}</main></div></div>;
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description?: string; actions?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="ink-label mb-2 text-primary">{eyebrow}</p><h1 className="font-[var(--app-font-serif)] text-[30px] font-bold tracking-[-.045em] text-foreground md:text-[35px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted-foreground">{description}</p>}</div>{actions && <div className="flex flex-wrap items-center gap-2">{actions}</div>}</div>;
}

function Button({ children, onClick, variant = 'primary', disabled, icon: Icon, testId, className }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'outline' | 'ghost' | 'danger'; disabled?: boolean; icon?: IconType; testId?: string; className?: string }) {
  return <button onClick={onClick} disabled={disabled} data-testid={testId} className={cls('inline-flex h-9 items-center justify-center gap-2 rounded-md px-3.5 text-xs font-bold transition-all active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-primary text-primary-foreground shadow-sm hover:bg-primary/90', variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary/50 hover:bg-muted', variant === 'ghost' && 'text-muted-foreground hover:bg-muted hover:text-foreground', variant === 'danger' && 'border border-destructive/30 bg-destructive/10 text-destructive hover:bg-destructive/15', className)}>{Icon && <Icon size={15} />}{children}</button>;
}
function StatusBadge({ value }: { value?: string | null }) {
  const raw = (value ?? 'pending').toLowerCase();
  const good = ['recovered', 'success', 'approved', 'retry', 'auto_retry', 'allowed'].some(x => raw.includes(x));
  const bad = ['failed', 'declined', 'blocked', 'escalat', 'skip'].some(x => raw.includes(x));
  const tone = good ? 'text-accent bg-accent/10 border-accent/20' : bad ? 'text-destructive bg-destructive/10 border-destructive/20' : 'text-primary bg-primary/10 border-primary/20';
  return <span className={cls('inline-flex items-center rounded border px-2 py-1 text-[10px] font-bold uppercase tracking-[.06em]', tone)} data-testid={`status-${raw.replaceAll(' ', '-')}`}>{value?.replaceAll('_', ' ') ?? 'Pending'}</span>;
}
function Metric({ label, value, detail, tone = 'orange', icon: Icon }: { label: string; value: string; detail: string; tone?: Tone; icon: IconType }) {
  const tones: Record<Tone, string> = { orange: 'bg-primary/10 text-primary', teal: 'bg-accent/10 text-accent', slate: 'bg-secondary text-secondary-foreground', yellow: 'bg-yellow-500/10 text-yellow-700 dark:text-yellow-300', red: 'bg-destructive/10 text-destructive' };
  return <div className="panel animate-rise-in p-4"><div className="flex items-start justify-between"><p className="ink-label">{label}</p><span className={cls('grid h-8 w-8 place-items-center rounded-md', tones[tone])}><Icon size={16} /></span></div><p className="mt-4 font-[var(--app-font-serif)] text-[27px] font-bold tracking-[-.045em]" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</p><p className="mt-1 text-[11px] text-muted-foreground">{detail}</p></div>;
}
function LoadingState({ rows = 4 }: { rows?: number }) { return <div className="space-y-3">{Array.from({ length: rows }).map((_, i) => <div key={i} className="h-14 animate-pulse rounded-md bg-muted" />)}</div>; }
function ErrorState({ onRetry }: { onRetry?: () => void }) { return <div className="panel flex min-h-[230px] flex-col items-center justify-center p-6 text-center"><CircleAlert className="mb-3 text-destructive" size={25} /><p className="font-semibold">We couldn't load this view</p><p className="mt-1 text-sm text-muted-foreground">The synthetic environment may be restarting.</p>{onRetry && <Button onClick={onRetry} variant="outline" className="mt-4" icon={RotateCcw} testId="button-retry">Try again</Button>}</div>; }

function RevenueChart({ points }: { points: Array<{ label: string; atRisk: number; recoverable: number; recovered: number }> }) {
  const safe = points?.length ? points : [];
  const max = Math.max(...safe.map(p => Math.max(p.atRisk, p.recoverable, p.recovered)), 1);
  const coords = (key: 'atRisk' | 'recoverable' | 'recovered') => safe.map((p, i) => `${(i / Math.max(safe.length - 1, 1)) * 100},${100 - (p[key] / max) * 86 - 4}`).join(' ');
  return <div className="panel p-5 md:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-bold">Revenue recovery curve</p><p className="mt-1 text-xs text-muted-foreground">Potential value against recovered value, trailing 30 days</p></div><div className="flex gap-3 text-[10px] font-semibold text-muted-foreground"><span><i className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-primary" />At risk</span><span><i className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-accent" />Recovered</span></div></div><div className="mt-6 h-[235px] w-full">{safe.length ? <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-full w-full overflow-visible"><defs><linearGradient id="riskFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="hsl(var(--primary))" stopOpacity=".16" /><stop offset="1" stopColor="hsl(var(--primary))" stopOpacity="0" /></linearGradient></defs>{[20, 40, 60, 80].map(y => <line key={y} x1="0" x2="100" y1={y} y2={y} stroke="hsl(var(--border))" strokeDasharray="1.5 2" strokeWidth=".35" />)}<polygon points={`0,100 ${coords('atRisk')} 100,100`} fill="url(#riskFill)" /><polyline points={coords('atRisk')} fill="none" stroke="hsl(var(--primary))" strokeWidth="1.2" vectorEffect="non-scaling-stroke" /><polyline points={coords('recoverable')} fill="none" stroke="hsl(var(--chart-4))" strokeWidth=".9" vectorEffect="non-scaling-stroke" strokeDasharray="4 3" /><polyline points={coords('recovered')} fill="none" stroke="hsl(var(--accent))" strokeWidth="1.3" vectorEffect="non-scaling-stroke" />{safe.map((p, i) => <circle key={i} cx={`${(i / Math.max(safe.length - 1, 1)) * 100}`} cy={100 - (p.recovered / max) * 86 - 4} r="1.3" fill="hsl(var(--accent))" />)}</svg> : <div className="grid h-full place-items-center text-sm text-muted-foreground">No chart data available</div>}</div><div className="mt-2 flex justify-between text-[10px] text-muted-foreground">{safe.filter((_, i) => i === 0 || i === Math.floor(safe.length / 2) || i === safe.length - 1).map((p, i) => <span key={`${p.label}-${i}`}>{p.label}</span>)}</div></div>;
}

function OverviewPage() {
  const query = useGetOverview({ query: { queryKey: getGetOverviewQueryKey() } });
  const runAgent = useRunRecoveryAgent();
  const resetAgent = useResetRecoveryAgent();
  const qc = useQueryClient();
  const overview = query.data;
  const [message, setMessage] = useState('');
  const run = () => runAgent.mutate(undefined, { onSuccess: result => { setMessage(result.message); qc.setQueryData(getGetOverviewQueryKey(), result.overview); qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }); qc.invalidateQueries({ queryKey: getListAuditLogQueryKey() }); } });
  const reset = () => resetAgent.mutate(undefined, { onSuccess: result => { setMessage('Environment reset. Ready for a clean run.'); qc.setQueryData(getGetOverviewQueryKey(), result); qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }); qc.invalidateQueries({ queryKey: getListAuditLogQueryKey() }); } });
  if (query.isLoading) return <><PageHeader eyebrow="Overview" title="Revenue recovery, at a glance" /><LoadingState rows={6} /></>;
  if (query.isError || !overview) return <ErrorState onRetry={() => query.refetch()} />;
  return <><PageHeader eyebrow="Thursday, October 24 · Synthetic environment" title="Revenue recovery, at a glance" description="A clear view of what failed, what can still be recovered, and what the agent would do next." actions={<><Button onClick={reset} variant="ghost" icon={RotateCcw} disabled={resetAgent.isPending} testId="button-reset-environment">Reset</Button><Button onClick={run} icon={runAgent.isPending ? Loader2 : Play} disabled={runAgent.isPending} testId="button-run-agent">{runAgent.isPending ? 'Running analysis…' : overview.agentRun ? 'Run again' : 'Run recovery agent'}</Button></>} /><div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Revenue at risk" value={formatMoney(overview.revenueAtRisk)} detail="Across failed payments" icon={WalletCards} tone="orange" /><Metric label="Potentially recoverable" value={formatMoney(overview.potentiallyRecoverable)} detail="Agent confidence ≥ threshold" icon={Target} tone="yellow" /><Metric label="Revenue recovered" value={formatMoney(overview.revenueRecovered)} detail={`${overview.recoveryRate}% recovery rate`} icon={ArrowUp} tone="teal" /><Metric label="Failed transactions" value={overview.failedTransactions.toLocaleString()} detail={`${overview.pendingManual} pending manual`} icon={CircleAlert} tone="red" /><Metric label="Successful recoveries" value={overview.successfulRecoveries.toLocaleString()} detail={`${overview.escalations} escalated`} icon={CircleCheck} tone="slate" /></div>{message && <div className="mb-5 flex items-center gap-2 rounded-md border border-accent/25 bg-accent/10 px-4 py-3 text-xs font-semibold text-accent animate-rise-in" data-testid="status-agent-message"><Check size={15} />{message}</div>}<div className="grid gap-5 xl:grid-cols-[1.65fr_1fr]"><RevenueChart points={overview.charts?.revenue ?? []} /><OutcomeBreakdown data={overview.charts?.outcomes ?? []} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1fr]"><FailureBreakdown title="Failure reasons" subtitle="Where the opportunity is concentrated" data={overview.charts?.failureReasons ?? []} /><ActionBreakdown data={overview.charts?.actions ?? []} /></div></>;
}

function OutcomeBreakdown({ data }: { data: Array<{ name: string; count: number; value: number }> }) { const total = data.reduce((s, x) => s + x.count, 0) || 1; return <div className="panel p-5 md:p-6"><p className="text-sm font-bold">Decision outcomes</p><p className="mt-1 text-xs text-muted-foreground">Current state of the synthetic queue</p><div className="mt-6 space-y-4">{data.length ? data.slice(0, 5).map((item, i) => <div key={item.name} className="animate-rise-in" style={{ animationDelay: `${i * 70}ms` }}><div className="mb-1.5 flex justify-between text-xs"><span className="font-semibold capitalize">{item.name.replaceAll('_', ' ')}</span><span className="mono text-muted-foreground">{item.count.toLocaleString()}</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={cls('h-full rounded-full', i === 0 ? 'bg-accent' : i === 1 ? 'bg-primary' : 'bg-secondary-foreground/40')} style={{ width: `${Math.max(3, item.count / total * 100)}%` }} /></div></div>) : <p className="py-8 text-center text-sm text-muted-foreground">No outcome data yet.</p>}</div></div>; }
function FailureBreakdown({ data, title, subtitle }: { data: Array<{ name: string; count: number; value: number }>; title: string; subtitle: string }) { return <div className="panel p-5 md:p-6"><p className="text-sm font-bold">{title}</p><p className="mt-1 text-xs text-muted-foreground">{subtitle}</p><div className="mt-5 space-y-2">{data.length ? data.slice(0, 6).map((item, i) => <div key={item.name} className="flex items-center justify-between border-b border-border/70 py-2.5 text-xs last:border-0"><span className="flex items-center gap-2 font-semibold"><span className={cls('h-1.5 w-1.5 rounded-full', i % 2 ? 'bg-accent' : 'bg-primary')} />{item.name}</span><span className="mono text-muted-foreground">{item.count} <span className="ml-2 text-foreground">{formatMoney(item.value)}</span></span></div>) : <p className="py-8 text-center text-sm text-muted-foreground">No failure data yet.</p>}</div></div>; }
function ActionBreakdown({ data }: { data: Array<{ name: string; count: number; value: number }> }) { return <div className="panel grid-paper p-5 md:p-6"><div className="flex items-center justify-between"><div><p className="text-sm font-bold">Agent action mix</p><p className="mt-1 text-xs text-muted-foreground">Recommended next moves</p></div><Sparkles size={19} className="text-primary" /></div><div className="mt-5 grid grid-cols-2 gap-2">{data.length ? data.slice(0, 4).map((item, i) => <div className="rounded-md border border-border bg-card/80 p-3" key={item.name}><p className="ink-label truncate">{item.name}</p><p className="mt-2 font-[var(--app-font-serif)] text-xl font-bold">{item.count}</p><p className="mt-1 text-[10px] text-muted-foreground">{formatMoney(item.value)} at stake</p></div>) : <p className="col-span-2 py-8 text-center text-sm text-muted-foreground">Run the agent to generate action mix.</p>}</div></div>; }

function TransactionsPage() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [failureReason, setFailureReason] = useState(''); const [outcome, setOutcome] = useState(''); const [page, setPage] = useState(1); const [sort, setSort] = useState('timestamp'); const [direction, setDirection] = useState<'asc' | 'desc'>('desc'); const [selected, setSelected] = useState<string | null>(null); const [filterOpen, setFilterOpen] = useState(false);
  const params = useMemo(() => ({ search: search || undefined, status: status || undefined, failureReason: failureReason || undefined, outcome: outcome || undefined, page, pageSize: 10, sort, sortDirection: direction }), [search, status, failureReason, outcome, page, sort, direction]);
  const query = useListTransactions(params, { query: { queryKey: getListTransactionsQueryKey(params), placeholderData: previous => previous } });
  return <><PageHeader eyebrow="Operations / payment queue" title="Transactions" description="Inspect every failed payment, from the first decline signal to the final recovery decision." actions={<Button onClick={() => downloadCsv('recoverai-transactions.csv', ['Transaction ID', 'Customer ID', 'Amount', 'Status'], (query.data?.items ?? []).map(item => [item.id, item.customerId, item.amount, item.status]))} variant="outline" icon={Download} testId="button-export-transactions">Export view</Button>} /><div className="panel mb-4 p-3"><div className="flex flex-col gap-2 md:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} data-testid="input-search-transactions" placeholder="Search transaction or customer ID…" className="h-9 w-full rounded-md border border-border bg-background pl-9 pr-3 text-xs outline-none ring-primary/20 placeholder:text-muted-foreground focus:ring-2" /></div><div className="flex flex-wrap gap-2"><select value={status} onChange={e => { setStatus(e.target.value); setPage(1); }} data-testid="select-transaction-status" className="h-9 rounded-md border border-border bg-background px-3 text-xs font-semibold outline-none"><option value="">All statuses</option><option value="FAILED">Failed</option><option value="SUCCEEDED">Succeeded</option></select><button onClick={() => setFilterOpen(open => !open)} data-testid="button-transaction-filters" className="inline-flex h-9 items-center gap-2 rounded-md border border-border px-3 text-xs font-bold hover:bg-muted"><Filter size={14} />Filters</button></div></div>{filterOpen && <div className="mt-3 grid gap-2 border-t border-border pt-3 text-[11px] text-muted-foreground sm:grid-cols-2"><label className="flex items-center gap-2">Failure reason<select value={failureReason} onChange={e => { setFailureReason(e.target.value); setPage(1); }} data-testid="select-transaction-failure-reason" className="h-8 min-w-0 flex-1 rounded-md border border-border bg-background px-2 text-xs font-semibold text-foreground"><option value="">All reasons</option>{['Insufficient funds','Network timeout','Authentication failure','Card expired','Bank decline','Daily limit exceeded'].map(reason => <option key={reason} value={reason}>{reason}</option>)}</select></label><label className="flex items-center gap-2">Outcome<select value={outcome} onChange={e => { setOutcome(e.target.value); setPage(1); }} data-testid="select-transaction-outcome" className="h-8 min-w-0 flex-1 rounded-md border border-border bg-background px-2 text-xs font-semibold text-foreground"><option value="">All outcomes</option><option value="SUCCESS">Success</option><option value="PENDING_MANUAL">Pending manual</option><option value="SKIPPED">Skipped</option><option value="FAILED">Failed</option></select></label></div>}</div>{query.isLoading ? <LoadingState rows={8} /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : <><div className="panel overflow-hidden"><div className="min-w-[900px] overflow-x-auto"><table className="w-full text-left"><thead className="border-b border-border bg-muted/50"><tr>{[['transaction','Transaction',''],['amount','Amount',''],['status','Status',''],['failure','Failure signal',''],['score','Score',''],['action','Recommended action',''],['timestamp','Observed','']].map(([key, label]) => <th key={key} className="px-4 py-3 ink-label">{key === 'amount' || key === 'score' || key === 'timestamp' ? <button onClick={() => { setSort(key === 'timestamp' ? 'timestamp' : key); setDirection(d => d === 'asc' ? 'desc' : 'asc'); }} className="inline-flex items-center gap-1" data-testid={`button-sort-${key}`}>{label}{sort === key && (direction === 'asc' ? <ArrowUp size={11} /> : <ArrowDown size={11} />)}</button> : label}</th>)}</tr></thead><tbody>{(query.data?.items ?? []).map((tx, i) => <TransactionRow key={tx.id} tx={tx} index={i} onClick={() => setSelected(tx.id)} />)}</tbody></table>{!query.data?.items?.length && <div className="p-14 text-center"><ListFilter className="mx-auto mb-3 text-muted-foreground" size={24} /><p className="text-sm font-semibold">No transactions match</p><p className="mt-1 text-xs text-muted-foreground">Try a different search or status filter.</p></div>}</div><div className="flex items-center justify-between border-t border-border px-4 py-3"><p className="text-[11px] text-muted-foreground">Showing <span className="font-bold text-foreground">{query.data?.items?.length ?? 0}</span> of <span className="font-bold text-foreground">{query.data?.total ?? 0}</span> transactions</p><div className="flex items-center gap-2"><Button variant="outline" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page <= 1} icon={ChevronLeft} testId="button-transactions-previous">Prev</Button><span className="mono px-2 text-[11px]">{query.data?.page ?? page} / {query.data?.totalPages ?? 1}</span><Button variant="outline" onClick={() => setPage(p => p + 1)} disabled={page >= (query.data?.totalPages ?? 1)} icon={ChevronRight} testId="button-transactions-next">Next</Button></div></div></div></>}{selected && <TransactionDrawer id={selected} onClose={() => setSelected(null)} />}</>;
}
function TransactionRow({ tx, index, onClick }: { tx: Transaction; index: number; onClick: () => void }) { return <tr onClick={onClick} data-testid={`row-transaction-${tx.id}`} className="animate-rise-in cursor-pointer border-b border-border/70 transition-colors hover:bg-muted/45" style={{ animationDelay: `${Math.min(index, 7) * 35}ms` }}><td className="px-4 py-3"><p className="mono text-xs font-medium">{tx.id}</p><p className="mt-1 text-[10px] text-muted-foreground">{tx.customerId}</p></td><td className="px-4 py-3"><p className="mono text-xs font-medium">{formatMoney(tx.amount, tx.currency)}</p><p className="mt-1 text-[10px] text-muted-foreground">{tx.paymentMethod}</p></td><td className="px-4 py-3"><StatusBadge value={tx.status} /></td><td className="max-w-[170px] px-4 py-3 text-xs font-semibold">{tx.failureReason ?? '—'}<p className="mt-1 text-[10px] font-normal text-muted-foreground">{tx.failureClassification ?? 'Unclassified'}</p></td><td className="px-4 py-3">{tx.recoveryScore == null ? <span className="text-xs text-muted-foreground">—</span> : <span className={cls('mono text-xs font-bold', tx.recoveryScore >= 70 ? 'text-accent' : tx.recoveryScore >= 45 ? 'text-primary' : 'text-destructive')}>{tx.recoveryScore}</span>}</td><td className="px-4 py-3 text-xs font-semibold capitalize">{tx.recommendedAction?.replaceAll('_', ' ') ?? 'Awaiting analysis'}</td><td className="whitespace-nowrap px-4 py-3 text-[11px] text-muted-foreground">{formatDate(tx.timestamp)}</td></tr>; }

function TransactionDrawer({ id, onClose }: { id: string; onClose: () => void }) { const query = useGetTransaction(id, { query: { queryKey: getGetTransactionQueryKey(id), enabled: Boolean(id) } }); return <div className="fixed inset-0 z-50 flex justify-end"><div className="absolute inset-0 bg-foreground/30" onClick={onClose} /><section className="relative h-full w-full max-w-[470px] overflow-y-auto border-l border-border bg-background p-6 shadow-2xl animate-rise-in"><div className="mb-8 flex items-center justify-between"><div><p className="ink-label text-primary">Transaction inspection</p><h2 className="mt-2 font-[var(--app-font-serif)] text-xl font-bold">{id}</h2></div><button onClick={onClose} data-testid="button-close-transaction" className="rounded-md p-2 text-muted-foreground hover:bg-muted"><X size={18} /></button></div>{query.isLoading ? <LoadingState rows={7} /> : query.isError || !query.data ? <ErrorState onRetry={() => query.refetch()} /> : <TransactionDetails tx={query.data} />}</section></div>; }
function TransactionDetails({ tx }: { tx: Transaction }) { const details = [['Customer ID', tx.customerId], ['Observed', formatDate(tx.timestamp)], ['Payment method', tx.paymentMethod], ['Failure class', tx.failureClassification ?? '—'], ['Retry count', String(tx.retryCount)], ['Recoverable amount', formatMoney(tx.recoverableAmount, tx.currency)]]; return <div className="space-y-6"><div className="flex items-center justify-between"><div><p className="ink-label">Current status</p><div className="mt-2"><StatusBadge value={tx.status} /></div></div><div className="text-right"><p className="ink-label">Payment value</p><p className="mt-2 mono text-2xl font-bold">{formatMoney(tx.amount, tx.currency)}</p></div></div><div className="grid grid-cols-2 gap-2">{details.map(([label, value]) => <div key={label} className="rounded-md border border-border bg-card p-3"><p className="ink-label">{label}</p><p className="mt-2 truncate text-xs font-semibold">{value}</p></div>)}</div><div className="rounded-md border border-primary/20 bg-primary/5 p-4"><div className="flex items-center gap-2 text-xs font-bold"><Sparkles size={15} className="text-primary" /> Decision</div><p className="mt-3 text-sm font-bold capitalize">{tx.recommendedAction?.replaceAll('_', ' ') ?? 'Awaiting analysis'}</p><p className="mt-2 text-xs leading-relaxed text-muted-foreground">{tx.decisionReason ?? 'No decision has been recorded for this transaction.'}</p></div><div><p className="ink-label mb-3">Guardrail review</p><div className="flex items-center justify-between border-b border-border py-3 text-xs"><span>Guardrail decision</span><StatusBadge value={tx.guardrailDecision} /></div><div className="flex items-center justify-between border-b border-border py-3 text-xs"><span>Final outcome</span><StatusBadge value={tx.finalOutcome} /></div></div></div>; }

function AgentPage() {
  const overviewQuery = useGetOverview({ query: { queryKey: getGetOverviewQueryKey() } }); const runAgent = useRunRecoveryAgent(); const resetAgent = useResetRecoveryAgent(); const qc = useQueryClient(); const [result, setResult] = useState<string | null>(null); const overview = overviewQuery.data;
  const run = () => runAgent.mutate(undefined, { onSuccess: res => { setResult(res.message); qc.setQueryData(getGetOverviewQueryKey(), res.overview); qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }); qc.invalidateQueries({ queryKey: getListAuditLogQueryKey() }); } }); const reset = () => resetAgent.mutate(undefined, { onSuccess: res => { setResult('Agent state reset. No decisions are pending.'); qc.setQueryData(getGetOverviewQueryKey(), res); qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }); qc.invalidateQueries({ queryKey: getListAuditLogQueryKey() }); } });
  if (overviewQuery.isLoading) return <><PageHeader eyebrow="Decision engine" title="Recovery agent" /><LoadingState rows={5} /></>; if (overviewQuery.isError || !overview) return <ErrorState onRetry={() => overviewQuery.refetch()} />;
  return <><PageHeader eyebrow="Decision engine / deterministic" title="Recovery agent" description="The agent evaluates every failed payment against a visible score and a strict policy layer. No black boxes, no side effects beyond this synthetic environment." actions={<><Button onClick={reset} variant="ghost" icon={RotateCcw} disabled={resetAgent.isPending} testId="button-reset-agent">Reset state</Button><Button onClick={run} icon={runAgent.isPending ? Loader2 : Play} disabled={runAgent.isPending} testId="button-run-agent-page">{runAgent.isPending ? 'Analyzing queue…' : 'Run recovery agent'}</Button></>} /><div className="grid gap-5 lg:grid-cols-[1.25fr_1fr]"><div className="panel overflow-hidden"><div className="border-b border-border bg-sidebar p-6 text-sidebar-foreground"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-md bg-sidebar-primary text-sidebar-primary-foreground"><Bot size={20} /></span><div><p className="text-sm font-bold">Recovery decision engine</p><p className="mt-1 text-[11px] text-sidebar-foreground/55">v2.4 · deterministic policy stack</p></div></div><span className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider text-accent"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-accent" />Ready</span></div><div className="mt-7 flex items-end justify-between"><div><p className="ink-label text-sidebar-foreground/45">Last analyzed</p><p className="mt-2 font-[var(--app-font-serif)] text-3xl font-bold">{overview.agentRun ? formatDate(new Date().toISOString()) : 'Not yet run'}</p></div><div className="text-right"><p className="ink-label text-sidebar-foreground/45">Queue size</p><p className="mt-2 mono text-2xl font-bold">{overview.failedTransactions}</p></div></div></div><div className="p-6"><p className="ink-label mb-4">Decision sequence</p><div className="space-y-0">{[['01','Classify','Read processor response and assign failure class.'],['02','Score','Estimate recovery probability from payment signals.'],['03','Apply policy','Check retry, value, cooldown, and score limits.'],['04','Commit','Write an explainable outcome to the audit log.']].map(([num, title, copy], i) => <div className="flex gap-4" key={num}><div className="flex flex-col items-center"><span className={cls('grid h-7 w-7 place-items-center rounded-full border text-[10px] font-bold', i < 3 ? 'border-primary/30 bg-primary/10 text-primary' : 'border-accent/30 bg-accent/10 text-accent')}>{i < 3 ? <Check size={13} /> : num}</span>{i < 3 && <span className="h-8 w-px bg-border" />}</div><div className="pb-5"><p className="text-xs font-bold">{title}</p><p className="mt-1 text-xs text-muted-foreground">{copy}</p></div></div>)}</div></div></div><div className="space-y-5"><div className="panel p-5"><p className="text-sm font-bold">Live run summary</p><p className="mt-1 text-xs text-muted-foreground">The latest committed decision set</p><div className="mt-5 grid grid-cols-2 gap-2"><MiniValue label="Analyzed" value={overview.failedTransactions.toLocaleString()} /><MiniValue label="Recovered" value={overview.successfulRecoveries.toLocaleString()} tone="teal" /><MiniValue label="Escalated" value={overview.escalations.toLocaleString()} tone="red" /><MiniValue label="Skipped" value={overview.skipped.toLocaleString()} /></div>{result && <div className="mt-4 rounded-md bg-accent/10 p-3 text-xs font-semibold text-accent" data-testid="text-agent-result">{result}</div>}</div><div className="panel p-5"><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 text-accent" size={19} /><div><p className="text-sm font-bold">Guardrails are active</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Every recommendation is checked against your policy before it can become an automatic action.</p><Link href="/guardrails" data-testid="link-review-guardrails" className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-primary hover:underline">Review guardrails <ExternalLink size={12} /></Link></div></div></div></div></div><div className="mt-5 panel p-5 md:p-6"><div className="flex items-center justify-between"><div><p className="text-sm font-bold">How scores become actions</p><p className="mt-1 text-xs text-muted-foreground">A readable model card for operators</p></div><SlidersHorizontal size={18} className="text-muted-foreground" /></div><div className="mt-5 grid gap-3 md:grid-cols-3"><ExplainCard icon={Target} title="Recovery score" copy="Signals like failure class, retry history, and payment method combine into a 0–100 confidence score." /><ExplainCard icon={ShieldCheck} title="Policy gate" copy="Thresholds and safety caps can override a high score when the value or timing is sensitive." /><ExplainCard icon={Zap} title="Action" copy="Allowed payments retry. Unclear cases escalate. Hard declines are safely skipped." /></div></div></>;
}
function MiniValue({ label, value, tone = 'orange' }: { label: string; value: string; tone?: 'orange' | 'teal' | 'red' }) { return <div className="rounded-md border border-border bg-muted/35 p-3"><p className="ink-label">{label}</p><p className={cls('mt-2 font-[var(--app-font-serif)] text-xl font-bold', tone === 'teal' ? 'text-accent' : tone === 'red' ? 'text-destructive' : 'text-primary')}>{value}</p></div>; }
function ExplainCard({ icon: Icon, title, copy }: { icon: IconType; title: string; copy: string }) { return <div className="rounded-md border border-border p-4"><Icon size={17} className="text-primary" /><p className="mt-3 text-xs font-bold">{title}</p><p className="mt-1.5 text-xs leading-relaxed text-muted-foreground">{copy}</p></div>; }

function AuditPage() {
  const [search, setSearch] = useState(''); const [outcome, setOutcome] = useState(''); const [page, setPage] = useState(1); const [selected, setSelected] = useState<AuditEntry | null>(null); const params = useMemo(() => ({ search: search || undefined, outcome: outcome || undefined, page, pageSize: 12 }), [search, outcome, page]); const query = useListAuditLog(params, { query: { queryKey: getListAuditLogQueryKey(params), placeholderData: previous => previous } });
  return <><PageHeader eyebrow="Operations / traceability" title="Audit log" description="A permanent decision trail for every recommendation, policy override, and committed outcome." actions={<Button onClick={() => downloadCsv('recoverai-audit-log.csv', ['Decision ID', 'Transaction ID', 'Score', 'Outcome'], (query.data?.items ?? []).map(item => [item.id, item.transactionId, item.aiScore, item.finalOutcome]))} variant="outline" icon={Download} testId="button-export-audit">Export log</Button>} /><div className="panel mb-4 p-3"><div className="flex flex-col gap-2 md:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} data-testid="input-search-audit" placeholder="Search transaction ID or failure reason…" className="h-9 w-full rounded-md border border-border bg-background pl-9 pr-3 text-xs outline-none focus:ring-2 focus:ring-primary/20" /></div><select value={outcome} onChange={e => { setOutcome(e.target.value); setPage(1); }} data-testid="select-audit-outcome" className="h-9 rounded-md border border-border bg-background px-3 text-xs font-semibold outline-none"><option value="">All outcomes</option><option value="SUCCESS">Success</option><option value="PENDING_MANUAL">Pending manual</option><option value="SKIPPED">Skipped</option><option value="FAILED">Failed</option></select></div></div>{query.isLoading ? <LoadingState rows={8} /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : <div className="panel overflow-hidden"><div className="min-w-[880px] overflow-x-auto"><table className="w-full text-left"><thead className="border-b border-border bg-muted/50"><tr>{['Decision time','Transaction','AI score','Failure reason','Recommendation','Policy gate','Outcome'].map(label => <th key={label} className="px-4 py-3 ink-label">{label}</th>)}</tr></thead><tbody>{(query.data?.items ?? []).map((entry, i) => <tr key={entry.id} onClick={() => setSelected(entry)} data-testid={`row-audit-${entry.id}`} className="animate-rise-in cursor-pointer border-b border-border/70 transition-colors hover:bg-muted/45" style={{ animationDelay: `${Math.min(i, 8) * 35}ms` }}><td className="whitespace-nowrap px-4 py-3 text-[11px] text-muted-foreground">{formatDate(entry.timestamp)}</td><td className="px-4 py-3 mono text-xs font-medium">{entry.transactionId}</td><td className="px-4 py-3"><span className={cls('mono text-xs font-bold', entry.aiScore >= 70 ? 'text-accent' : entry.aiScore >= 45 ? 'text-primary' : 'text-destructive')}>{entry.aiScore}</span></td><td className="px-4 py-3 text-xs font-semibold">{entry.failureReason}</td><td className="px-4 py-3 text-xs font-semibold capitalize">{entry.recommendedAction.replaceAll('_', ' ')}</td><td className="px-4 py-3"><StatusBadge value={entry.guardrailDecision} /></td><td className="px-4 py-3"><StatusBadge value={entry.finalOutcome} /></td></tr>)}</tbody></table>{!query.data?.items?.length && <div className="p-14 text-center"><BookOpen className="mx-auto mb-3 text-muted-foreground" size={24} /><p className="text-sm font-semibold">The trail is empty</p><p className="mt-1 text-xs text-muted-foreground">Run the recovery agent to create your first decision records.</p></div>}</div><div className="flex items-center justify-between border-t border-border px-4 py-3"><p className="text-[11px] text-muted-foreground">{query.data?.total ?? 0} decisions recorded</p><div className="flex items-center gap-2"><Button variant="outline" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page <= 1} icon={ChevronLeft} testId="button-audit-previous">Prev</Button><span className="mono px-2 text-[11px]">{query.data?.page ?? page} / {query.data?.totalPages ?? 1}</span><Button variant="outline" onClick={() => setPage(p => p + 1)} disabled={page >= (query.data?.totalPages ?? 1)} icon={ChevronRight} testId="button-audit-next">Next</Button></div></div></div>}{selected && <AuditDrawer entry={selected} onClose={() => setSelected(null)} />}</>;
}
function AuditDrawer({ entry, onClose }: { entry: AuditEntry; onClose: () => void }) { return <div className="fixed inset-0 z-50 flex justify-end"><div className="absolute inset-0 bg-foreground/30" onClick={onClose} /><section className="relative h-full w-full max-w-[470px] overflow-y-auto border-l border-border bg-background p-6 shadow-2xl animate-rise-in"><div className="mb-8 flex items-center justify-between"><div><p className="ink-label text-primary">Decision record</p><h2 className="mt-2 font-[var(--app-font-serif)] text-xl font-bold">{entry.transactionId}</h2></div><button onClick={onClose} data-testid="button-close-audit" className="rounded-md p-2 text-muted-foreground hover:bg-muted"><X size={18} /></button></div><div className="space-y-5"><div className="grid grid-cols-2 gap-2"><MiniValue label="AI score" value={`${entry.aiScore}/100`} /><div className="rounded-md border border-border bg-muted/35 p-3"><p className="ink-label">Decision time</p><p className="mt-2 text-xs font-semibold">{formatDate(entry.timestamp)}</p></div></div><div className="rounded-md border border-primary/20 bg-primary/5 p-4"><p className="ink-label text-primary">Recommendation</p><p className="mt-2 text-sm font-bold capitalize">{entry.recommendedAction.replaceAll('_', ' ')}</p><p className="mt-2 text-xs leading-relaxed text-muted-foreground">{entry.reasoning}</p></div><div className="space-y-3"><div className="flex items-center justify-between text-xs"><span>Failure reason</span><span className="font-semibold">{entry.failureReason}</span></div><div className="flex items-center justify-between text-xs"><span>Guardrail decision</span><StatusBadge value={entry.guardrailDecision} /></div><div className="flex items-center justify-between text-xs"><span>Final outcome</span><StatusBadge value={entry.finalOutcome} /></div></div></div></section></div>; }

function GuardrailsPage() {
  const query = useGetGuardrails({ query: { queryKey: getGetGuardrailsQueryKey() } }); const mutation = useUpdateGuardrails(); const qc = useQueryClient(); const [form, setForm] = useState<GuardrailsInput | null>(null); const [saved, setSaved] = useState(false);
  useEffect(() => { if (query.data && !form) setForm({ ...query.data }); }, [query.data, form]);
  const update = (key: keyof GuardrailsInput, value: string) => setForm(current => current ? { ...current, [key]: Number(value) } : current); const save = () => { if (!form) return; mutation.mutate({ data: form }, { onSuccess: value => { setForm({ ...value }); setSaved(true); qc.setQueryData(getGetGuardrailsQueryKey(), value); setTimeout(() => setSaved(false), 2600); } }); };
  if (query.isLoading || !form) return <><PageHeader eyebrow="Policy / controls" title="Guardrails" /><LoadingState rows={6} /></>; if (query.isError) return <ErrorState onRetry={() => query.refetch()} />;
  const fields: Array<{ key: keyof GuardrailsInput; label: string; description: string; suffix: string; min: number; max?: number }> = [{ key: 'minimumRecoveryScore', label: 'Minimum recovery score', description: 'Scores below this level are never eligible for automatic recovery.', suffix: '/ 100', min: 0, max: 100 }, { key: 'maximumAutomaticRecoveryAmount', label: 'Maximum automatic recovery amount', description: 'Payments above this value require an operator to approve the action.', suffix: 'USD', min: 0 }, { key: 'maximumRetryAttempts', label: 'Maximum retry attempts', description: 'A payment will never be retried more than this many times.', suffix: 'attempts', min: 0, max: 10 }, { key: 'cooldownMinutes', label: 'Cooldown between retries', description: 'Minimum time between automated attempts on the same payment.', suffix: 'minutes', min: 1, max: 1440 }, { key: 'highValueThreshold', label: 'High-value threshold', description: 'Marks transactions above this value for additional scrutiny.', suffix: 'USD', min: 0 }];
  return <><PageHeader eyebrow="Policy / safety" title="Guardrails" description="Set the boundaries that keep recovery decisions useful, explainable, and safe. Changes apply to the next agent run." actions={<><Button onClick={() => query.data && setForm({ maximumRetryAttempts: query.data.maximumRetryAttempts, highValueThreshold: query.data.highValueThreshold, cooldownMinutes: query.data.cooldownMinutes, minimumRecoveryScore: query.data.minimumRecoveryScore, maximumAutomaticRecoveryAmount: query.data.maximumAutomaticRecoveryAmount })} variant="ghost" icon={RotateCcw} testId="button-reset-guardrails">Discard changes</Button><Button onClick={save} disabled={mutation.isPending} icon={mutation.isPending ? Loader2 : Check} testId="button-save-guardrails">{mutation.isPending ? 'Saving…' : 'Save guardrails'}</Button></>} />{saved && <div className="mb-5 flex items-center gap-2 rounded-md border border-accent/25 bg-accent/10 px-4 py-3 text-xs font-semibold text-accent animate-rise-in" data-testid="status-guardrails-saved"><Check size={15} />Guardrails saved. The next run will use these controls.</div>}<div className="grid gap-5 lg:grid-cols-[1.4fr_1fr]"><div className="panel p-5 md:p-7"><div className="mb-6 flex items-center gap-3 border-b border-border pb-5"><span className="grid h-9 w-9 place-items-center rounded-md bg-primary/10 text-primary"><SlidersHorizontal size={17} /></span><div><p className="text-sm font-bold">Recovery policy</p><p className="mt-1 text-xs text-muted-foreground">Automatic action thresholds</p></div></div><div className="space-y-6">{fields.map(field => <label key={field.key} className="block"><span className="flex items-center justify-between text-xs font-bold"><span>{field.label}</span><span className="mono text-primary">{form[field.key]} {field.suffix}</span></span><span className="mt-1.5 block text-[11px] leading-relaxed text-muted-foreground">{field.description}</span><div className="mt-3 flex items-center gap-3"><input type="range" min={field.min} max={field.max ?? Math.max(Number(form[field.key]) * 2, 1000)} step={field.key === 'cooldownMinutes' ? 1 : field.key === 'maximumAutomaticRecoveryAmount' || field.key === 'highValueThreshold' ? 5 : 1} value={Number(form[field.key])} onChange={e => update(field.key, e.target.value)} data-testid={`input-${field.key}`} className="h-1.5 flex-1 cursor-pointer accent-[hsl(var(--primary))]" /><input type="number" min={field.min} max={field.max} value={Number(form[field.key])} onChange={e => update(field.key, e.target.value)} className="h-9 w-[92px] rounded-md border border-border bg-background px-2 text-right mono text-xs outline-none focus:ring-2 focus:ring-primary/20" /></div></label>)}</div></div><div className="space-y-5"><div className="panel grid-paper p-5 md:p-6"><p className="text-sm font-bold">Policy preview</p><p className="mt-1 text-xs text-muted-foreground">What the agent will enforce</p><div className="mt-5 space-y-3"><PolicyLine icon={ShieldCheck} label="Automatic retries" value={`Score ≥ ${form.minimumRecoveryScore}`} /><PolicyLine icon={WalletCards} label="Value cap" value={`Up to ${formatMoney(form.maximumAutomaticRecoveryAmount)}`} /><PolicyLine icon={Clock3} label="Cooldown" value={`${form.cooldownMinutes} minutes`} /><PolicyLine icon={CircleAlert} label="High-value review" value={`Above ${formatMoney(form.highValueThreshold)}`} /></div></div><div className="rounded-md border border-yellow-600/20 bg-yellow-500/10 p-5"><div className="flex gap-3"><CircleAlert className="mt-0.5 shrink-0 text-yellow-700 dark:text-yellow-300" size={18} /><div><p className="text-xs font-bold text-yellow-800 dark:text-yellow-200">Synthetic mode only</p><p className="mt-1.5 text-xs leading-relaxed text-yellow-800/70 dark:text-yellow-100/65">These controls demonstrate policy behavior. No payment processor or customer is contacted by RecoverAI.</p></div></div></div></div></div></>;
}
function PolicyLine({ icon: Icon, label, value }: { icon: IconType; label: string; value: string }) { return <div className="flex items-center gap-3 rounded-md border border-border bg-card/70 p-3"><Icon size={15} className="text-primary" /><span className="flex-1 text-xs font-semibold">{label}</span><span className="mono text-[10px] text-muted-foreground">{value}</span></div>; }

function SettingsPage() { const [safe, setSafe] = useState(true); const [dense, setDense] = useState(false); const [saved, setSaved] = useState(false); const save = () => { setSaved(true); setTimeout(() => setSaved(false), 2200); }; return <><PageHeader eyebrow="Workspace / configuration" title="Settings" description="Configure the synthetic workspace experience for your finance and operations team." actions={<Button onClick={save} icon={saved ? Check : undefined} testId="button-save-settings">{saved ? 'Saved' : 'Save settings'}</Button>} />{saved && <div className="mb-5 rounded-md border border-accent/25 bg-accent/10 px-4 py-3 text-xs font-semibold text-accent animate-rise-in" data-testid="status-settings-saved">Workspace preferences updated.</div>}<div className="grid gap-5 lg:grid-cols-[1.4fr_1fr]"><div className="space-y-5"><SettingsSection icon={Database} title="Synthetic environment" description="The data source and behavior used for this workspace"><SettingRow label="Environment" description="All data is generated and safe to explore." right={<span className="inline-flex items-center gap-1.5 rounded border border-accent/20 bg-accent/10 px-2 py-1 text-[10px] font-bold uppercase text-accent"><span className="h-1.5 w-1.5 rounded-full bg-accent" />Synthetic</span>} /><SettingRow label="Dataset" description="October payment recovery benchmark" right={<button data-testid="button-change-dataset" className="text-xs font-bold text-primary hover:underline">Change</button>} /><SettingRow label="Data retention" description="Decisions are kept for 30 days in demo mode." right={<span className="mono text-xs text-muted-foreground">30 days</span>} /></SettingsSection><SettingsSection icon={ShieldCheck} title="Safety & access" description="Keep your evaluation environment safely separated"><SettingRow label="Safe mode" description="Block all external payment and communication actions." right={<Toggle checked={safe} onChange={() => setSafe(!safe)} testId="toggle-safe-mode" />} /><SettingRow label="Require review for high value" description="Always pause recommendations above the high-value threshold." right={<Toggle checked={true} onChange={() => undefined} testId="toggle-high-value" />} /></SettingsSection></div><div className="space-y-5"><SettingsSection icon={SlidersHorizontal} title="Application" description="Tune the command center to your working style"><SettingRow label="Compact tables" description="Show more transactions per screen." right={<Toggle checked={dense} onChange={() => setDense(!dense)} testId="toggle-compact-tables" />} /><SettingRow label="Timezone" description="Used for activity timestamps." right={<span className="text-xs font-semibold">UTC−07:00</span>} /></SettingsSection><div className="panel p-5"><div className="flex items-start gap-3"><LifeBuoy size={18} className="text-primary" /><div><p className="text-sm font-bold">Need a hand?</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Read the operator guide to understand how scores, guardrails, and outcomes connect.</p><button data-testid="button-open-guide" className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-primary hover:underline">Open operator guide <ExternalLink size={12} /></button></div></div></div></div></div></>; }
function SettingsSection({ icon: Icon, title, description, children }: { icon: IconType; title: string; description: string; children: ReactNode }) { return <section className="panel p-5 md:p-6"><div className="mb-4 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-md bg-secondary text-secondary-foreground"><Icon size={17} /></span><div><h2 className="text-sm font-bold">{title}</h2><p className="mt-1 text-xs text-muted-foreground">{description}</p></div></div><div className="divide-y divide-border">{children}</div></section>; }
function SettingRow({ label, description, right }: { label: string; description: string; right: ReactNode }) { return <div className="flex items-center justify-between gap-4 py-4 first:pt-2 last:pb-1"><div><p className="text-xs font-bold">{label}</p><p className="mt-1 max-w-md text-[11px] leading-relaxed text-muted-foreground">{description}</p></div><div className="shrink-0">{right}</div></div>; }
function Toggle({ checked, onChange, testId }: { checked: boolean; onChange: () => void; testId: string }) { return <button onClick={onChange} data-testid={testId} aria-pressed={checked} className={cls('relative h-6 w-11 rounded-full transition-colors', checked ? 'bg-accent' : 'bg-muted-foreground/30')}><span className={cls('absolute top-1 h-4 w-4 rounded-full bg-background shadow-sm transition-transform', checked ? 'translate-x-6' : 'translate-x-1')} /></button>; }

function NotFound() { return <div className="panel mx-auto max-w-lg p-12 text-center"><CircleAlert className="mx-auto mb-4 text-primary" size={28} /><h1 className="font-[var(--app-font-serif)] text-2xl font-bold">Page not found</h1><p className="mt-2 text-sm text-muted-foreground">This control room does not have that destination.</p><Link href="/" data-testid="link-back-overview" className="mt-5 inline-flex text-xs font-bold text-primary hover:underline">Back to overview</Link></div>; }
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function Router() { return <RoutedErrorBoundary><Shell><Switch><Route path="/" component={OverviewPage} /><Route path="/transactions" component={TransactionsPage} /><Route path="/recovery-agent" component={AgentPage} /><Route path="/audit-log" component={AuditPage} /><Route path="/guardrails" component={GuardrailsPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell></RoutedErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;
